  function toolbar(){const st=store.snapshot(),queued=st.outbox.filter(x=>x.status!=='acknowledged').length;const preview=(route,label)=>`<a href="#/${route}" ${path===route||route==='dispatch'&&!document.body.classList.contains?.('experience')?'aria-current="page"':''}>${label}</a>`;return `<div class="prototype-bar"><span class="workspace-state">${offline()?icon('alert'):'<span class="connection-dot" aria-hidden="true"></span>'}<span class="ws-label">Local prototype</span>${offline()?' · Offline':''}${!store.persistent()?' · Storage unavailable':''}${queued?` · ${queued} waiting to sync`:''}</span>${langSwitch()}<nav class="preview-roles" aria-label="Preview roles">${preview('dispatch','Dispatcher')}${preview('customer','Buyer')}${preview('ride','Rider')}</nav><details class="prototype-tools"><summary>Demo tools</summary><div class="prototype-menu"><p>${st.clockMode==='fixed'?'Test clock':'Yangon time'}: ${esc(localTime().replace('T',' '))}</p><p>${store.persistent()?'Saved on this device.':'Storage is blocked. Changes last only for this session.'}</p><a href="#/scenarios">Test scenarios</a></div></details></div>`;}

  function statusSign(){const c=laneCounts(ownOrders()),p=store.snapshot().policy,cut=`${String(Math.floor(p.cutoff/60)).padStart(2,'0')}:${String(p.cutoff%60).padStart(2,'0')}`,calm=!c.waiting,none=!ownOrders().length;return `<div class="status-sign ${calm?'calm':''}" role="status"><div class="now"><strong class="num">${esc(localTime().slice(11))}</strong><span>Yangon</span></div><div class="msg">${none?'No orders yet today':calm?'Every buyer has answered':`${c.waiting} ${c.waiting===1?'buyer hasn’t':'buyers haven’t'} answered`}<span>${p.enforceCutoff?`Buyer changes close at ${cut}`:'Buyers can change details until the van leaves'}</span></div></div>`;}
